import { useEffect, useState } from "react";
import "./Pedidos.css";
import axios from "axios";

export default function Pedidos() {

  const [sales, setSales] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user"));

    if (!user || !user.identificacion) {
      console.log("Usuario no encontrado en localStorage");
      setLoading(false);
      return;
    }

    axios
      .get(`https://backend-cozyhome.onrender.com/api/sales/user/${user.identificacion}`)
      .then(res => {
        console.log("Ventas recibidas:", res.data);
        setSales(res.data || []);
      })
      .catch(err => {
        console.error("Error al traer pedidos:", err);
      })
      .finally(() => {
        setLoading(false);
      });

  }, []);

  if (loading) {
    return <div className="container mt-4"><p>Cargando pedidos...</p></div>;
  }

  return (
    <div className="container mt-4">
      <h2>Mis pedidos</h2>

      {sales.length === 0 ? (
        <p>No has comprado aún</p>
      ) : (
        sales.map(sale => (
          <div key={sale.id_sale} className="card mb-4">
            <div className="card-header">
              Compra #{sale.id_sale}
            </div>

            <div className="card-body">
              <p>
                Total: $
                {Number(sale.total).toLocaleString("es-CO")}
              </p>

              <p>Estado: {sale.estado}</p>

              <ul className="list-group">
                {sale.detalles && sale.detalles.length > 0 ? (
                  sale.detalles.map(d => (
                    <li key={d.id_detail} className="list-group-item">
                      <strong>{d.nombre_producto}</strong><br />
                      Precio: ${Number(d.precio).toLocaleString("es-CO")}<br />
                      Cantidad: {d.cantidad}
                    </li>
                  ))
                ) : (
                  <li className="list-group-item">
                    Sin detalles
                  </li>
                )}
              </ul>
            </div>
          </div>
        ))
      )}
    </div>
  );
}
